function studioEnsure(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$repo=new InMemoryMethodologyStudioRepository();$studio=new MethodologyStudioService($repo);$org='org';$studio->create($org,['slug'=>'sales-studio','name'=>'Sales Diagnostic','domain'=>'Sales','methodology_version'=>'0.2.0'],'admin');$source=json_decode(file_get_contents(dirname(__DIR__,2).'/resources/diagnostic/sales/0.1.0/sales-diagnostic-pack.json'),true,512,JSON_THROW_ON_ERROR);$map=['sections'=>'AREA','criteria'=>'CRITERION','facts'=>'FACT','metrics'=>'METRIC','questions'=>'QUESTION','evidence_requirements'=>'EVIDENCE_REQUIREMENT','rules'=>'RULE','dependencies'=>'DEPENDENCY','recommendations'=>'RECOMMENDATION','benchmarks'=>'BENCHMARK','scoring'=>'SCORING'];foreach($map as $key=>$type)foreach($source[$key]??[] as $i=>$entity)$studio->saveEntity($org,'sales-studio','0.2.0',$type,$entity+['order'=>$i],'admin');$validation=$studio->validate($org,'sales-studio','0.2.0');studioEnsure($validation['valid'],'Studio pack failed validation: '.implode(';',$validation['errors']));$metrics=[];foreach($source['metrics'] as $m)$metrics[$m['id']]=$m['direction']==='lower_is_better'?10:90;$facts=array_fill_keys(array_column($source['facts'],'id'),true);$simulation=$studio->simulate($org,'sales-studio','0.2.0',['facts'=>$facts,'metrics'=>$metrics]);studioEnsure($simulation['score']!==null&&$simulation['coverage']===1.0,'Studio simulator failed.');$studio->saveScenario($org,'sales-studio','0.2.0',['id'=>'healthy','name'=>'Healthy','input'=>['facts'=>$facts,'metrics'=>$metrics],'expected'=>['findings'=>[]]],'admin');$regression=$studio->runRegression($org,'sales-studio','0.2.0');studioEnsure($regression['failed']===0&&count($repo->results)===1,'Regression runner did not persist results.');$studio->publish($org,'sales-studio','0.2.0','publisher');studioEnsure($repo->version($org,'sales-studio','0.2.0')['status']==='PUBLISHED'&&$repo->packsData[$org]['sales-studio']['active_methodology_version']==='0.2.0','Publish workflow failed.');try{$studio->saveEntity($org,'sales-studio','0.2.0','FACT',$source['facts'][0],'admin');throw new RuntimeException('Published pack was mutable.');}catch(DomainException){}$studio->clone($org,'sales-studio','0.2.0','0.3.0','admin');studioEnsure($repo->version($org,'sales-studio','0.3.0')['status']==='DRAFT'&&count($studio->entities($org,'sales-studio','0.3.0'))===count($studio->entities($org,'sales-studio','0.2.0')),'Clone workflow failed.');studioEnsure(count($repo->audits)>200,'Methodology audit was not recorded.');$expression=new MetricExpressionEngine();studioEnsure(abs($expression->evaluate('median(first_contact - created) / 60',['first_contact'=>[160,280,400],'created'=>[100,100,100]])-3.0)<0.0001,'Deterministic metric expression failed.');try{$expression->evaluate('system("whoami")',[]);throw new RuntimeException('Unsafe formula syntax was accepted.');}catch(InvalidArgumentException){}echo "Diagnostic Methodology Studio workflow passed.\n";
